import requests
from bs4 import BeautifulSoup
import pandas as pd
from io import StringIO
def task_func(url, table_id):
    response = requests.get(url)
    response.raise_for_status()
    soup = BeautifulSoup(response.text, 'html.parser')
    table = soup.find('table', id=table_id)
    if table is None:
        raise ValueError("Table with the specified ID not found.")
    rows = table.find_all('tr')
    if not rows:
        return pd.DataFrame()
    headers = []
    data_rows = []
    for i, row in enumerate(rows):
        ths = row.find_all('th')
        tds = row.find_all('td')
        if ths and i == 0:
            headers = [th.get_text(strip=True) for th in ths]
        elif tds:
            data_rows.append([td.get_text(strip=True) for td in tds])
    if not data_rows:
        return pd.DataFrame(columns=headers if headers else None)
    df = pd.DataFrame(data_rows, columns=headers if headers else None)
    return df

