import requests
from lxml import html
import pandas as pd
import sqlite3
def task_func(webpage_url: str, database_name: str = "my_database.db") -> int:
    try:
        response = requests.get(webpage_url)
        response.raise_for_status()
    except requests.RequestException as e:
        raise requests.RequestException(f"Network error: {e}")
    try:
        tree = html.fromstring(response.content)
        table_element = tree.xpath('//table')
        if not table_element:
            return 0
        html_string = html.tostring(table_element[0], encoding='unicode')
        dfs = pd.read_html(html_string)
        if not dfs:
            return 0
        df = dfs[0]
        if df.empty:
            return 0
        rows_count = len(df)
    except Exception as e:
        raise requests.RequestException(f"Error parsing HTML: {e}")
    try:
        conn = sqlite3.connect(database_name)
        df.to_sql('my_table', conn, if_exists='replace', index=False)
        conn.close()
    except sqlite3.DatabaseError as e:
        raise sqlite3.DatabaseError(f"Database error: {e}")
    return rows_count

import requests
from lxml import html
import pandas as pd
import sqlite3
def task_func(webpage_url: str, database_name: str = "my_database.db") -> int:
    if not isinstance(webpage_url, str) or not webpage_url:
        raise ValueError("Invalid webpage URL provided.")
    try:
        response = requests.get(webpage_url)
        response.raise_for_status()
    except requests.RequestException as e:
        raise requests.RequestException(f"Failed to fetch URL: {e}")
    try:
        tree = html.fromstring(response.content)
        table = tree.find('.//table')
        if table is None:
            return 0
        headers_elements = table.findall('.//th')
        headers = [th.text_content().strip() for th in headers_elements] if headers_elements else None
        rows = table.findall('.//tr')
        data = []
        for row in rows:
            cols = row.findall('.//td')
            if cols:
                data.append([col.text_content().strip() for col in cols])
        if not data:
            return 0
        df = pd.DataFrame(data, columns=headers if headers else None)
    except Exception as e:
        raise ValueError(f"Error parsing HTML: {e}")
    try:
        conn = sqlite3.connect(database_name)
        df.to_sql('my_table', conn, if_exists='replace', index=False)
        conn.close()
    except sqlite3.DatabaseError as e:
        raise sqlite3.DatabaseError(f"Database error: {e}")
    return len(df)

