import re
import json
import requests
def task_func(data_url: str) -> list:
    try:
        response = requests.get(data_url)
        data = response.json()
        names = []
        def extract_strings(obj):
            if isinstance(obj, dict):
                for v in obj.values():
                    extract_strings(v)
            elif isinstance(obj, list):
                for item in obj:
                    extract_strings(item)
            elif isinstance(obj, str):
                matches = re.findall(r'(?<!\[)\b[A-Za-z ]+\b(?!\])', obj)
                names.extend(matches)
        extract_strings(data)
        return names
    except Exception:
        return "Invalid url input"

import re
import json
import requests
def task_func(data_url: str) -> list:
    try:
        response = requests.get(data_url)
        data = response.json()
        text = json.dumps(data)
        names = re.findall(r'\b[A-Z][a-z]+\b', text)
        bracketed = re.findall(r'\[.*?\]', text)
        for b in bracketed:
            names_in_brackets = re.findall(r'\b[A-Z][a-z]+\b', b)
            for n in names_in_brackets:
                if n in names:
                    names.remove(n)
        return names
    except Exception:
        return "Invalid url input"

