import requests
import os
import zipfile
def task_func(url, destination_directory, headers=None):
    if not url or not destination_directory:
        raise ValueError("URL and destination directory must be provided.")
    try:
        response = requests.get(url, headers=headers, stream=True)
        response.raise_for_status()
    except requests.RequestException as e:
        raise ConnectionError(f"Failed to download zip file: {e}")
    os.makedirs(destination_directory, exist_ok=True)
    try:
        with zipfile.ZipFile(response.raw) as zf:
            zf.extractall(destination_directory)
            extracted_files = zf.namelist()
    except zipfile.BadZipFile as e:
        raise IOError(f"Failed to extract zip file: {e}")
    return extracted_files

